#include <format>
#include <iostream>
#include <string_view>

// Principal moments of inertia about the centre of mass, in kg m^2.
struct Inertia {
  double ixx;
  double iyy;
  double izz;
};

struct Box {
  double x_m;
  double y_m;
  double z_m;
};

// A cylinder's axis is its own z axis, in SDF and in URDF.
struct Cylinder {
  double radius_m;
  double length_m;
};

[[nodiscard]] constexpr Inertia solid_box(double mass_kg, Box b) {
  return {.ixx = mass_kg / 12.0 * (b.y_m * b.y_m + b.z_m * b.z_m),
          .iyy = mass_kg / 12.0 * (b.x_m * b.x_m + b.z_m * b.z_m),
          .izz = mass_kg / 12.0 * (b.x_m * b.x_m + b.y_m * b.y_m)};
}

[[nodiscard]] constexpr Inertia solid_cylinder(double mass_kg, Cylinder c) {
  const double across = mass_kg / 12.0 * (3.0 * c.radius_m * c.radius_m + c.length_m * c.length_m);
  return {.ixx = across, .iyy = across, .izz = mass_kg / 2.0 * c.radius_m * c.radius_m};
}

[[nodiscard]] constexpr Inertia solid_sphere(double mass_kg, double radius_m) {
  const double i = 2.0 / 5.0 * mass_kg * radius_m * radius_m;
  return {.ixx = i, .iyy = i, .izz = i};
}

// Positive moments, and none larger than the sum of the other two.
[[nodiscard]] constexpr bool physical(Inertia i) {
  return i.ixx > 0 && i.iyy > 0 && i.izz > 0 && i.ixx + i.iyy >= i.izz && i.iyy + i.izz >= i.ixx &&
         i.izz + i.ixx >= i.iyy;
}

void print_sdf(std::string_view link, double mass_kg, Inertia i) {
  std::cout << std::format("{:<13} <mass>{}</mass> <ixx>{:.6g}</ixx> <iyy>{:.6g}</iyy> <izz>{:.6g}</izz>  {}\n", link,
                           mass_kg, i.ixx, i.iyy, i.izz, physical(i) ? "physical" : "NOT physical");
}

int main() {
  print_sdf("chassis", 4.0, solid_box(4.0, {.x_m = 0.30, .y_m = 0.20, .z_m = 0.10}));
  print_sdf("wheel", 0.2, solid_cylinder(0.2, {.radius_m = 0.05, .length_m = 0.03}));
  print_sdf("caster", 0.05, solid_sphere(0.05, 0.025));
  print_sdf("chassis in mm", 4.0, solid_box(4.0, {.x_m = 300, .y_m = 200, .z_m = 100}));
  print_sdf("typo", 1.0, {.ixx = 0.01, .iyy = 0.01, .izz = 0.1});
}
